package com.ptc.halo;
import com.ptc.halo.entity.*;import com.ptc.halo.enums.*;import com.ptc.halo.repository.*;import com.ptc.halo.service.*;
import org.junit.jupiter.api.*;import org.springframework.test.util.ReflectionTestUtils;import org.springframework.web.server.ResponseStatusException;
import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class LessonAttachmentAccessTest {
 AiLearningFileRepository files=mock(AiLearningFileRepository.class);LessonMaterialStorage storage=mock(LessonMaterialStorage.class);
 UserRepository users=mock(UserRepository.class);StudentProfileRepository profiles=mock(StudentProfileRepository.class);StudentSubjectEnrollmentRepository enrollments=mock(StudentSubjectEnrollmentRepository.class);
 AiLearningModuleRepository modules=mock(AiLearningModuleRepository.class);WeekRepository weeks=mock(WeekRepository.class);StudentModuleProgressRepository progress=mock(StudentModuleProgressRepository.class);
 UserEntity student=new UserEntity();AiLearningModuleEntity module=new AiLearningModuleEntity();AiLearningFileEntity file=new AiLearningFileEntity();SubjectEntity subject=new SubjectEntity();WeekEntity week=new WeekEntity();LessonAttachmentService service;StudentLearningProgressionService progression;
 @BeforeEach void setup() throws Exception {
  student.setId(1L);student.setRole(Role.STUDENT);student.setStatus(Status.ACTIVE);ReflectionTestUtils.setField(subject,"id",2L);subject.setYearLevel(YearLevel.FIRST_YEAR);ReflectionTestUtils.setField(week,"id",3L);week.setSubject(subject);week.setWeekNumber(1);module.setId(4L);module.setWeek(week);module.setStatus(LessonStatus.APPROVED);module.setAiGenerationStatus(AiGenerationStatus.COMPLETED);file.setId(5L);file.setModule(module);file.setFilePath("opaque");file.setFileType("application/pdf");file.setOriginalFileName("../lesson\r\n.pdf");module.addFile(file);
  var profile=new StudentProfileEntity();profile.setYearLevel(YearLevel.FIRST_YEAR);when(profiles.findByUserId(1L)).thenReturn(Optional.of(profile));when(enrollments.existsByStudent_IdAndSubject_IdAndActiveTrue(1L,2L)).thenReturn(true);when(modules.findById(4L)).thenReturn(Optional.of(module));when(modules.findByWeekId(3L)).thenReturn(Optional.of(module));when(weeks.findBySubject_IdOrderByWeekNumberAsc(2L)).thenReturn(List.of(week));when(files.findById(5L)).thenReturn(Optional.of(file));when(storage.read("opaque")).thenReturn(new byte[]{1,2});
  progression=new StudentLearningProgressionService(weeks,mock(SubjectRepository.class),modules,progress,new StudentLessonAccessService(users,profiles,enrollments));service=new LessonAttachmentService(files,storage,progression);
 }
 @Test void enrolledStudentReadsAndMetadataHasNoInternalPaths() throws Exception {assertArrayEquals(new byte[]{1,2},service.student(5L,student).bytes());var response=new StudentLessonService(modules,progression).byWeek(3L,student);String json=new com.fasterxml.jackson.databind.ObjectMapper().writeValueAsString(response.getFiles());assertTrue(json.contains("originalFileName"));assertFalse(json.contains("filePath"));assertFalse(json.contains("storedFileName"));assertFalse(json.contains("opaque"));assertEquals("lesson__.pdf",response.getFiles().get(0).getOriginalFileName());}
 @Test void inactiveEnrollmentAndOtherStudentCannotReadKnownFileId() {when(enrollments.existsByStudent_IdAndSubject_IdAndActiveTrue(1L,2L)).thenReturn(false);assertEquals("ENROLLMENT_REQUIRED",assertThrows(ResponseStatusException.class,()->service.student(5L,student)).getReason());student.setId(99L);assertThrows(ResponseStatusException.class,()->service.student(5L,student));verifyNoInteractions(storage);}
 @Test void changedYearAndUnpublishedModuleRemainDenied() {subject.setYearLevel(YearLevel.SECOND_YEAR);assertThrows(ResponseStatusException.class,()->service.student(5L,student));subject.setYearLevel(YearLevel.FIRST_YEAR);module.setStatus(LessonStatus.PENDING);assertThrows(ResponseStatusException.class,()->service.student(5L,student));verifyNoInteractions(storage);}
 @Test void lockedWeekRemainsDenied() {var previous=new WeekEntity();ReflectionTestUtils.setField(previous,"id",8L);previous.setWeekNumber(1);week.setWeekNumber(2);when(weeks.findBySubject_IdOrderByWeekNumberAsc(2L)).thenReturn(List.of(previous,week));assertEquals("PREVIOUS_WEEK_INCOMPLETE",assertThrows(ResponseStatusException.class,()->service.student(5L,student)).getReason());verifyNoInteractions(storage);}
 @Test void enrollmentIsRecheckedAfterRemoteRead() throws Exception {when(storage.read("opaque")).thenAnswer(call->{when(enrollments.existsByStudent_IdAndSubject_IdAndActiveTrue(1L,2L)).thenReturn(false);return new byte[]{1};});assertEquals("ENROLLMENT_REQUIRED",assertThrows(ResponseStatusException.class,()->service.student(5L,student)).getReason());}
 @Test void professorOwnershipIsIndependentFromStudentAccess() {var professor=new UserEntity();professor.setId(10L);professor.setRole(Role.PROFESSOR);professor.setStatus(Status.ACTIVE);assertThrows(ResponseStatusException.class,()->service.professor(5L,professor));verifyNoInteractions(storage);when(files.findByIdAndModule_Week_Subject_Professor_User_Id(5L,10L)).thenReturn(Optional.of(file));assertArrayEquals(new byte[]{1,2},service.professor(5L,professor).bytes());}
}
